{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/member-row.json
    One member of TeamGrid beside a small portrait: the name, the role, then the department and the place (detailed, directory), the bio (detailed) and the skills (detailed, list).
    Props (p): member, depts, layout. *}
{var $v_member = ($p['member'] ?? null)}
{var $v_depts = ($p['depts'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'list')}
{capture $c_11}
  {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_member, ['name']), 'ratio' => '1/1', 'className' => ui_cnv([ui_cnv([(ui_t(ui_eq($v_layout, 'detailed')) ? 'size-16' : 'size-12'), 'shrink-0'])])]])|noescape}
  {capture $c_10}
    {capture $c_3}
      {capture $c_1}
        {=ui_text(ui_get($v_member, ['name']))}
      {/capture}
      {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'base', 'Weight' => 'semibold'], 'children' => $c_1])|noescape}
      {capture $c_2}
        {=ui_text(ui_get($v_member, ['role']))}
      {/capture}
      {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
    {/capture}
    {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '0'], 'children' => $c_3])|noescape}
    {if ui_t(!(ui_eq($v_layout, 'list')))}
      {capture $c_6}
        {capture $c_4}
          {=ui_text(ui_at($v_depts, ui_get($v_member, ['dept'])))}
        {/capture}
        {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'outline', 'Size' => 'sm'], 'children' => $c_4])|noescape}
        {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'map-pin', 'Size' => 16]])|noescape}
        {capture $c_5}
          {=ui_text(ui_get($v_member, ['location']))}
        {/capture}
        {=ui_include('ui/inline/inline.latte', ['p' => [], 'children' => $c_5])|noescape}
      {/capture}
      {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Align' => 'center', 'Class' => 'flex-wrap text-xs text-muted-foreground'], 'children' => $c_6])|noescape}
    {/if}
    {if ui_t(ui_eq($v_layout, 'detailed'))}
      {capture $c_7}
        {=ui_text(ui_get($v_member, ['bio']))}
      {/capture}
      {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_7])|noescape}
    {/if}
    {if ui_t(!(ui_eq($v_layout, 'directory')))}
      {capture $c_9}
        {foreach ui_l(ui_get($v_member, ['skills'])) as $v_k}
          {capture $c_8}
            {=ui_text($v_k)}
          {/capture}
          {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'secondary', 'Size' => 'sm'], 'children' => $c_8])|noescape}
        {/foreach}
      {/capture}
      {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Class' => 'flex-wrap'], 'children' => $c_9])|noescape}
    {/if}
  {/capture}
  {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Class' => 'min-w-0 flex-1'], 'children' => $c_10])|noescape}
{/capture}
{=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Align' => 'start', 'Class' => ui_s((ui_t(ui_eq($v_layout, 'detailed')) ? 'rounded bg-card inset-ring inset-ring-border flex-col p-6' : (ui_t(ui_eq($v_layout, 'directory')) ? 'rounded bg-card inset-ring inset-ring-border p-4' : 'border-b border-border pb-4'))), 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_11])|noescape}
